import json
import httpx
from fastmcp import Server


def create_mcp_server_from_openapi(
    openapi_spec: dict,
    http_client: httpx.AsyncClient,
) -> Server:
    """
    Create an MCP server from an OpenAPI 3.0 specification.

    Args:
        openapi_spec: OpenAPI 3.0 specification as a dict
        http_client: Configured httpx.AsyncClient with base URL set

    Returns:
        FastMCP Server instance with tools for each API operation
    """
    server = Server("openapi-mcp")

    for path, path_item in openapi_spec.get("paths", {}).items():
        for method, operation in path_item.items():
            if method.lower() not in ["get", "post", "put", "delete", "patch", "head", "options"]:
                continue

            operation_id = operation.get("operationId", f"{method}_{path}".replace("/", "_").replace("-", "_"))
            description = operation.get("description") or operation.get("summary") or ""
            parameters = operation.get("parameters", [])
            request_body = operation.get("requestBody")

            # Build input schema
            properties = {}
            required_fields = []

            for param in parameters:
                param_name = param.get("name")
                if param_name:
                    param_schema = param.get("schema", {})
                    properties[param_name] = {
                        "type": param_schema.get("type", "string"),
                        "description": param.get("description", ""),
                    }
                    if param.get("required"):
                        required_fields.append(param_name)

            if request_body:
                properties["body"] = {
                    "type": "object",
                    "description": "Request body",
                }
                if request_body.get("required"):
                    required_fields.append("body")

            input_schema = {
                "type": "object",
                "properties": properties,
            }
            if required_fields:
                input_schema["required"] = required_fields

            # Create handler with proper closure
            def create_handler(http_method, url_path, params, has_body):
                async def handler(**kwargs) -> str:
                    url = url_path
                    query_params = {}
                    headers = {}
                    json_body = None

                    for param in params:
                        param_name = param.get("name")
                        param_in = param.get("in")
                        param_value = kwargs.get(param_name)

                        if param_value is not None:
                            if param_in == "path":
                                url = url.replace(f"{{{param_name}}}", str(param_value))
                            elif param_in == "query":
                                query_params[param_name] = param_value
                            elif param_in == "header":
                                headers[param_name] = param_value

                    if has_body and "body" in kwargs:
                        json_body = kwargs["body"]

                    try:
                        response = await http_client.request(
                            http_method.upper(),
                            url,
                            params=query_params if query_params else None,
                            headers=headers if headers else None,
                            json=json_body,
                        )
                        response.raise_for_status()
                        return json.dumps({
                            "status": response.status_code,
                            "data": response.json(),
                        })
                    except httpx.HTTPError as e:
                        return json.dumps({
                            "error": str(e),
                            "status": getattr(e.response, "status_code", None) if hasattr(e, "response") else None,
                        })

                return handler

            handler_func = create_handler(method, path, parameters, bool(request_body))

            # Register the tool
            server.add_tool(
                handler_func,
                name=operation_id,
                description=description,
                inputSchema=input_schema,
            )

    return server


